import json

def transform(grid):
    result = []
    for row in grid:
        if len(row) == 0:
            result.append([])
            continue

        # Find the length of the prefix of identical cells
        prefix_len = 1
        for i in range(1, len(row)):
            if row[i] == row[0]:
                prefix_len += 1
            else:
                break

        # If the whole row is uniform, keep it unchanged
        if prefix_len == len(row):
            result.append(row[:])
        else:
            # Keep prefix, convert rest to 1
            result.append(row[:prefix_len] + [1]*(len(row)-prefix_len))
    return result

